const plan = $json;
const list = (items) => (items || []).map((item) => `- ${item}`).join('
');
const criteria = (plan.criterios_aceptacion || []).map((item) => `- [ ] ${item}`).join('
');
const files = list(plan.archivos_probables);
const technicalPlan = list(plan.plan_tecnico);
const tests = list(plan.pruebas_requeridas);
const risks = list(plan.riesgos) || '- Ninguno indicado';

return [{
  json: {
    ...plan,
    issueTitle: `[Agente] ${plan.titulo}`,
    issueBody: `## Historia de usuario

${plan.historia_usuario}

## Criterios de aceptación

${criteria}

## Plan técnico

${technicalPlan}

## Archivos probables

${files}

## Pruebas requeridas

${tests}

## Riesgos

${risks}

## Instrucciones para Copilot coding agent

- Trabaja en una branch nueva basada en develop.
- No modifiques develop directamente.
- No leas ni modifiques archivos .env ni secretos.
- Implementa todos los criterios de aceptación.
- Ejecuta las pruebas indicadas y reporta resultados reales.
- Abre un Pull Request contra develop.
- No hagas merge automático.

> Este Issue fue generado por el workflow de n8n. La asignación a Copilot coding agent y la aprobación del merge requieren revisión humana.`
  }
}];

