const instruccion = ($json.chatInput || $json.instruccion || '').trim();
if (!instruccion) {
  throw new Error(
    'Falta chatInput/instruccion: envía un mensaje desde el chat de n8n o rellena instruccion en la ejecución manual.'
  );
}
const chatSessionId = $json.sessionId || $json.session_id || $json.conversationId || 'greenline-default';
const state = $getWorkflowStaticData('global');
state.opencodeHistories = state.opencodeHistories || {};
const history = (state.opencodeHistories[chatSessionId] || [])
  .filter(m =>
    m &&
    (m.role === 'user' || m.role === 'assistant') &&
    typeof m.content === 'string' &&
    m.content.trim() !== ''
  )
  .slice(-20);
const opencodeUrl = ('https://opencode.ai/zen/go/v1').replace(/\/$/, '');
const model = 'deepseek-v4-flash';

const projectContext = [
  'CONTEXTO DEL PROYECTO GREENLINE (repo idmr023/greenline, branch develop):',
  '- Greenline Web ERP: e-commerce + ERP de vehículos eléctricos en Perú.',
  '- Stack: React 19, Vite, Tailwind CSS v4, Supabase (PostgreSQL + RLS). Backend Express 5 + Prisma en backend/. Scripts Node con Sharp.',
  '- Estructura: frontend/components (UI), frontend/pages (23 páginas, routing file-based en src/routes.jsx), frontend/hooks, frontend/lib (supabase.js, api.js, services), src/ (main.jsx, App.jsx, routes.jsx), supabase/ (schema, seed, migrations RLS), scripts/, docs/, .github/workflows.',
  '- Convenciones (AGENTS.md): no añadir librerías sin justificación; consultas DB solo vía frontend/lib/supabase.js o api.js; respetar RLS; imágenes con npm run sync_image; validar con npm run lint, npm run security-smoke, npm run build.',
  '- Naming: camelCase variables/funciones, PascalCase componentes y archivos de página.',
  '- Pipeline issue→Copilot: issue en idmr023/greenline con label agent-request, branch base develop, dispatch a .github/copilot-agent.yml (inputs issue_numero, issueBody). No merge automático.',
  ''
].join('\n');

const cache = state.githubContextCache || null;
const githubCacheFresh = !!(cache && cache.text && (Date.now() - (cache.at || 0) < 3600000));
const githubContext = githubCacheFresh ? cache.text : '';

const systemPrompt = projectContext
  + (githubContext ? '\n\nCONTEXTO DEL REPOSITORIO (AGENTS.md, README, ARQUITECTURA, KNOWLEDGE_BASE, árbol develop):\n' + githubContext + '\n' : '')
  + '\nResponde UNICAMENTE con JSON valido y exactamente este esquema: {titulo:string,historia_usuario:string,criterios_aceptacion:string[],archivos_probables:string[],plan_tecnico:string[],pruebas_requeridas:string[],riesgos:string[],preguntas_pendientes:string[],listo_para_implementar:boolean}. Integra aclaraciones del usuario y marca listo_para_implementar=false si faltan datos. Si el usuario responde aclaraciones, actualiza el plan completo con todo lo conversado. Usa el contexto del repositorio para proponer archivos_probables y plan_tecnico realistas.'
  + '\nREGLAS DE preguntas_pendientes (obligatorias):'
  + '\n- Solo dudas BLOQUEantes reales que impiden implementar (siempre en forma de pregunta concreta y accionable).'
  + '\n- Si no hay bloqueos: preguntas_pendientes DEBE ser [] (array vacio).'
  + '\n- NUNCA pongas texto tipo "no hay preguntas", "ninguna", comentarios, estado del test ni meta-texto en preguntas_pendientes.'
  + '\n- Si listo_para_implementar=true entonces preguntas_pendientes=[].'
  + '\n- Si listo_para_implementar=false entonces incluye al menos 1 pregunta bloqueante concreta.';

const messages = [
  { role: 'system', content: systemPrompt },
  ...history,
  { role: 'user', content: instruccion }
];

return [{
  json: {
    ...$json,
    instruccion,
    chatSessionId,
    opencodeUrl,
    model,
    messages,
    githubCacheFresh,
    githubContext
  }
}];

const decode = (nodeName) => {
  try {
    const j = $node[nodeName].json;
    if (j && j.encoding === 'base64' && typeof j.content === 'string') {
      return Buffer.from(j.content.replace(/\n/g, ''), 'base64').toString('utf8');
    }
    if (j && typeof j.content === 'string' && j.content.length > 0 && !j.encoding) {
      return j.content;
    }
  } catch (e) {}
  return '';
};

const agents = decode('Obtener AGENTS.md');
const readme = decode('Obtener README.md');
const arq = decode('Obtener ARQUITECTURA.md');
const kb = decode('Obtener KNOWLEDGE_BASE.md');

let treeLines = [];
try {
  const treeJson = $node['Obtener árbol develop'].json;
  if (treeJson && Array.isArray(treeJson.tree)) {
    treeLines = treeJson.tree
      .filter((t) => t.type === 'blob'
        && !t.path.startsWith('node_modules')
        && !t.path.startsWith('dist/')
        && !t.path.startsWith('.git/')
        && t.path.length < 180)
      .map((t) => t.path)
      .slice(0, 500);
  }
} catch (e) {}

const parts = [];
if (agents) parts.push('## AGENTS.md\n' + agents.slice(0, 5000));
if (readme) parts.push('## README.md\n' + readme.slice(0, 4000));
if (arq) parts.push('## ARQUITECTURA.md\n' + arq.slice(0, 4000));
if (kb) parts.push('## docs/KNOWLEDGE_BASE.md\n' + kb.slice(0, 8000));
if (treeLines.length) parts.push('## Árbol del repo (develop)\n' + treeLines.join('\n'));

const githubContext = parts.join('\n\n');
const state = $getWorkflowStaticData('global');
state.githubContextCache = { at: Date.now(), text: githubContext };

const prep = $node['Preparar pedido del chat'].json;
const marker = 'CONTEXTO DEL REPOSITORIO';
let baseSystem = prep.messages[0].content;
const idx = baseSystem.indexOf(marker);
if (idx >= 0) {
  const schemaIdx = baseSystem.indexOf('Responde UNICAMENTE con JSON');
  baseSystem = baseSystem.slice(0, idx) + (schemaIdx >= 0 ? baseSystem.slice(schemaIdx) : '');
}
const systemContent = baseSystem
  + (githubContext ? '\n\nCONTEXTO DEL REPOSITORIO (AGENTS.md, README, ARQUITECTURA, KNOWLEDGE_BASE, árbol develop):\n' + githubContext + '\n' : '')
  + (baseSystem.includes('Responde UNICAMENTE') ? '' : '\nResponde UNICAMENTE con JSON valido y exactamente este esquema: {titulo:string,historia_usuario:string,criterios_aceptacion:string[],archivos_probables:string[],plan_tecnico:string[],pruebas_requeridas:string[],riesgos:string[],preguntas_pendientes:string[],listo_para_implementar:boolean}. Integra aclaraciones del usuario y marca listo_para_implementar=false si faltan datos. Usa el contexto del repositorio para proponer archivos_probables y plan_tecnico realistas.');

const messages = [
  { role: 'system', content: systemContent },
  ...prep.messages.slice(1)
].filter(m =>
  m &&
  (m.role === 'system' || m.role === 'user' || m.role === 'assistant') &&
  typeof m.content === 'string' &&
  m.content.trim() !== ''
);

return [{
  json: {
    ...prep,
    messages,
    githubCacheFresh: true,
    githubContext
  }
}];

