// 1. Extraer y validar el contenido de la respuesta
const choices = $json.choices || [];
const first = choices[0] || {};
const content = first.message && first.message.content;
const finishReason = first.finish_reason || '';

if (!content || typeof content !== 'string') {
  throw new Error('OpenCode no devolvio contenido en choices[0].message.content (finish_reason=' + finishReason + ')');
}

// 2. Detectar truncado por max_tokens antes de parsear
if (finishReason === 'length') {
  throw new Error(
    'Respuesta truncada por max_tokens (finish_reason=length, ' + content.length + ' chars). Sube max_tokens en Enviar pedido a OpenCode o pide un plan mas corto.'
  );
}

// 3. Limpiar la respuesta y parsear a JSON
const text = content.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
let plan;
try {
  plan = JSON.parse(text);
} catch (e) {
  const truncated = /Unterminated|unexpected end|JSON.{0,20}truncat/i.test(e.message);
  throw new Error(
    (truncated
      ? 'Respuesta OpenCode truncada o JSON incompleto (finish_reason=' + finishReason + '): '
      : 'Respuesta OpenCode no es JSON valido: ')
    + e.message
  );
}

// 3b. Normalizar preguntas_pendientes / listo_para_implementar
if (!Array.isArray(plan.preguntas_pendientes)) {
  plan.preguntas_pendientes = [];
}
plan.preguntas_pendientes = plan.preguntas_pendientes
  .filter(q => typeof q === 'string' && q.trim() !== '')
  .map(q => q.trim())
  .filter(q => !/no hay (preguntas|dudas|aclaraciones|bloqueantes)|ninguna pregunta|^n\/a$|^ninguno$|^ninguna$/i.test(q));

if (plan.listo_para_implementar === true) {
  plan.preguntas_pendientes = [];
} else if (plan.preguntas_pendientes.length === 0) {
  plan.preguntas_pendientes = ['Indica qué falta para dar el plan por listo.'];
}
plan.listo_para_implementar = plan.listo_para_implementar === true;

// 4. Datos preparados del nodo anterior
const prep = $node['Preparar pedido del chat'].json;
const chatSessionId = prep.chatSessionId || 'default';
const instruccion = (prep.instruccion || '').trim();

// 5. Memoria: no guardar el JSON crudo del plan (infla el contexto y provoca truncado en el 2.º turno)
const state = $getWorkflowStaticData('global');
state.opencodeHistories = state.opencodeHistories || {};
const history = state.opencodeHistories[chatSessionId] || [];

if (instruccion) {
  history.push({ role: 'user', content: instruccion });
}
const tituloPlan = typeof plan.titulo === 'string' && plan.titulo.trim() ? plan.titulo.trim() : 'sin titulo';
const listo = plan.listo_para_implementar ? 'listo_para_implementar=true' : 'listo_para_implementar=false';
const pendientes = plan.preguntas_pendientes.length
  ? '; preguntas_pendientes=' + plan.preguntas_pendientes.length
  : '';
history.push({
  role: 'assistant',
  content: 'Plan generado: ' + tituloPlan + ' (' + listo + pendientes + '). El JSON completo esta en la ultima ejecucion del workflow.'
});

// Limitar a los ultimos 40 mensajes para no saturar
state.opencodeHistories[chatSessionId] = history.slice(-40);

// 6. Retornar el plan estructurado
return [{ json: plan }];
